"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { createClient } from "@/lib/supabase/client";

function callbackUrl(origin: string, next: string, promo: boolean) {
  const url = new URL("/auth/callback", origin);
  url.searchParams.set("next", next);
  url.searchParams.set("promo", promo ? "1" : "0");
  return url.toString();
}

export function AuthForm() {
  const router = useRouter();
  const supabase = useMemo(() => { try { return createClient(); } catch { return null; } }, []);
  const [mode, setMode] = useState<"signin" | "signup">("signup");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [anonymous, setAnonymous] = useState(false);
  const [identityChecked, setIdentityChecked] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    async function inspectIdentity() {
      if (!supabase) { if (!cancelled) setIdentityChecked(true); return; }
      const { data } = await supabase.auth.getUser();
      if (!cancelled) {
        setAnonymous(Boolean(data.user?.is_anonymous));
        setIdentityChecked(true);
      }
    }
    void inspectIdentity().catch(() => { if (!cancelled) setIdentityChecked(true); });
    return () => { cancelled = true; };
  }, [supabase]);

  async function claimPromo() {
    await fetch("/api/auth/claim-signup-promo", { method: "POST", headers: { "content-type": "application/json" }, body: "{}" });
  }

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (!supabase || !identityChecked) return;
    setBusy(true); setMessage(null);
    try {
      if (mode === "signup" && anonymous) {
        const redirectTo = callbackUrl(window.location.origin, "/auth/update-password?upgrade=1", true);
        const { data, error } = await supabase.auth.updateUser({ email }, { emailRedirectTo: redirectTo });
        if (error) throw error;
        if (data.user && !data.user.is_anonymous) {
          await claimPromo();
          router.push("/auth/update-password?upgrade=1");
          router.refresh();
          return;
        }
        setMessage("Check your email to verify this address. After verification you will choose a password; this keeps the same guest user, credits, and history.");
        return;
      }

      if (mode === "signup") {
        const redirectTo = callbackUrl(window.location.origin, "/account", true);
        const { data, error } = await supabase.auth.signUp({ email, password, options: { emailRedirectTo: redirectTo } });
        if (error) throw error;
        if (data.session) {
          await claimPromo();
          router.push("/account");
          router.refresh();
          return;
        }
        setMessage("Check your email to confirm the account. The one-time signup credit grant is claimed after confirmation.");
        return;
      }

      if (anonymous) {
        setMessage("This browser currently has a guest account with its own credit history. To avoid silently replacing that guest session, convert it with Sign up or Google instead of signing into a different existing account here.");
        return;
      }
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      if (error) throw error;
      router.push("/account");
      router.refresh();
    } catch (cause) {
      setMessage(cause instanceof Error ? cause.message : "Authentication could not be completed.");
    } finally { setBusy(false); }
  }

  async function google() {
    if (!supabase || !identityChecked) return;
    setBusy(true); setMessage(null);
    const redirectTo = callbackUrl(window.location.origin, "/account", mode === "signup" || anonymous);
    const result = anonymous
      ? await supabase.auth.linkIdentity({ provider: "google", options: { redirectTo } })
      : await supabase.auth.signInWithOAuth({ provider: "google", options: { redirectTo } });
    if (result.error) { setMessage("Google sign-in could not be started."); setBusy(false); }
  }

  async function resetPassword() {
    if (!supabase || !email) { setMessage("Enter your email first."); return; }
    if (anonymous) { setMessage("Convert or leave the current guest session before requesting a password reset for another account."); return; }
    setBusy(true); setMessage(null);
    const redirectTo = `${window.location.origin}/auth/update-password`;
    const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo });
    setMessage(error ? error.message : "If the address is eligible, a password-reset email has been sent.");
    setBusy(false);
  }

  const anonymousUpgrade = anonymous && mode === "signup";
  return <div className="panel">
    <div className="panel-heading"><div><p className="eyebrow">Account</p><h2>{anonymousUpgrade ? "Keep this guest account" : mode === "signup" ? "Create an account" : "Sign in"}</h2></div><span className="pill">+3 signup credits once</span></div>
    {anonymous && <div className="notice-card">A guest session is active. Converting it preserves the same Supabase user ID so existing guest credits and ledger history stay attached.</div>}
    <div className="actions"><button type="button" className={mode === "signup" ? "primary" : "ghost"} onClick={() => { setMode("signup"); setMessage(null); }}>Sign up</button><button type="button" className={mode === "signin" ? "primary" : "ghost"} onClick={() => { setMode("signin"); setMessage(null); }}>Sign in</button></div>
    <form onSubmit={submit}>
      <label>Email<input type="email" autoComplete="email" required value={email} onChange={event => setEmail(event.target.value)} /></label>
      {!anonymousUpgrade && <label>Password<input type="password" minLength={8} autoComplete={mode === "signup" ? "new-password" : "current-password"} required value={password} onChange={event => setPassword(event.target.value)} /></label>}
      {anonymousUpgrade && <p className="privacy-note">Supabase requires the email identity to be verified before a password can be added to an anonymous user. We will send the verification first, then ask you to choose the password.</p>}
      <div className="actions"><button className="primary" disabled={busy || !supabase || !identityChecked} type="submit">{busy ? "Working…" : anonymousUpgrade ? "Verify email and keep guest history" : mode === "signup" ? "Create account" : "Sign in"}</button><button className="secondary" disabled={busy || !supabase || !identityChecked} type="button" onClick={google}>{anonymous ? "Link Google and keep guest history" : "Continue with Google"}</button>{mode === "signin" && <button className="ghost" disabled={busy} type="button" onClick={resetPassword}>Forgot password</button>}</div>
    </form>
    <p className="privacy-note">Guest upgrades use Supabase identity linking instead of creating a replacement user. Ordinary sign-in never claims the signup promotion.</p>
    {message && <div className="notice-card" role="status">{message}</div>}
  </div>;
}

import { strFromU8, strToU8, unzipSync, zipSync } from "fflate";
import type { FileFinding } from "./types";

const CORE_FIELDS = ["dc:creator", "cp:lastModifiedBy", "dc:title", "dc:subject", "cp:keywords", "dc:description", "dcterms:created", "dcterms:modified"];
const APP_FIELDS = ["Application", "AppVersion", "Company", "Manager", "Template"];
const MAX_DOCX_ENTRIES = 2_048;
const MAX_DOCX_ENTRY_BYTES = 32 * 1024 * 1024;
const MAX_DOCX_TOTAL_BYTES = 64 * 1024 * 1024;
const MAX_DOCX_COMPRESSION_RATIO = 250;

function unzipDocxSafely(bytes: Uint8Array) {
  let entryCount = 0;
  let totalUncompressed = 0;
  unzipSync(bytes, {
    filter(info) {
      entryCount += 1;
      if (entryCount > MAX_DOCX_ENTRIES) throw new Error("DOCX package contains too many entries.");
      if (info.originalSize > MAX_DOCX_ENTRY_BYTES) throw new Error("DOCX package contains an oversized entry.");
      totalUncompressed += info.originalSize;
      if (totalUncompressed > MAX_DOCX_TOTAL_BYTES) throw new Error("DOCX package expands beyond the safe processing limit.");
      const ratio = info.size === 0 ? (info.originalSize === 0 ? 1 : Number.POSITIVE_INFINITY) : info.originalSize / info.size;
      if (ratio > MAX_DOCX_COMPRESSION_RATIO) throw new Error("DOCX package has a suspicious compression ratio.");
      if (info.name.startsWith("/") || info.name.includes("../") || info.name.includes("..\\")) throw new Error("DOCX package contains an unsafe entry path.");
      return false;
    },
  });
  return unzipSync(bytes);
}

function hasMeaningfulContent(xml: string, tags: string[]) {
  return tags.some((tag) => {
    const match = new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)<\\/${tag}>`, "i").exec(xml);
    return Boolean(match?.[1]?.trim());
  });
}

function blankTags(xml: string, tags: string[]) {
  let result = xml;
  for (const tag of tags) {
    const pattern = new RegExp(`(<${tag}\\b[^>]*>)[\\s\\S]*?(<\\/${tag}>)`, "gi");
    result = result.replace(pattern, "$1$2");
  }
  return result;
}

export function inspectDocx(bytes: Uint8Array): FileFinding[] {
  const zip = unzipDocxSafely(bytes);
  const findings: FileFinding[] = [];
  const core = zip["docProps/core.xml"] ? strFromU8(zip["docProps/core.xml"]) : "";
  const app = zip["docProps/app.xml"] ? strFromU8(zip["docProps/app.xml"]) : "";
  const custom = zip["docProps/custom.xml"] ? strFromU8(zip["docProps/custom.xml"]) : "";

  if (core && hasMeaningfulContent(core, CORE_FIELDS)) {
    findings.push({ id: "docx-core", kind: "office_core", disposition: "privacy_metadata", label: "DOCX core properties", description: "Author, editor, title, timestamps, keywords, or other core document properties are present.", removableByDefault: true });
  }
  if (app && hasMeaningfulContent(app, APP_FIELDS)) {
    findings.push({ id: "docx-app", kind: "office_app", disposition: "privacy_metadata", label: "DOCX application properties", description: "Application, version, company, manager, or template metadata is present.", removableByDefault: true });
  }
  if (custom && /<property\b/i.test(custom)) {
    findings.push({ id: "docx-custom", kind: "office_custom", disposition: "privacy_metadata", label: "DOCX custom properties", description: "Custom Office properties are embedded in the package.", removableByDefault: true });
  }
  return findings;
}

export function sanitizeDocx(bytes: Uint8Array): Uint8Array {
  const zip = unzipDocxSafely(bytes);
  if (zip["docProps/core.xml"]) {
    zip["docProps/core.xml"] = strToU8(blankTags(strFromU8(zip["docProps/core.xml"]), CORE_FIELDS));
  }
  if (zip["docProps/app.xml"]) {
    zip["docProps/app.xml"] = strToU8(blankTags(strFromU8(zip["docProps/app.xml"]), APP_FIELDS));
  }
  if (zip["docProps/custom.xml"]) {
    const custom = strFromU8(zip["docProps/custom.xml"]).replace(/<property\b[\s\S]*?<\/property>/gi, "");
    zip["docProps/custom.xml"] = strToU8(custom);
  }
  return zipSync(zip, { level: 6 });
}

import type { C2paValidationItem, C2paVerificationReceipt, C2paVerificationStatus } from "./types";

type UnknownRecord = Record<string, unknown>;

const asRecord = (value: unknown): UnknownRecord | null =>
  value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as UnknownRecord)
    : null;

function normalizeValidationItems(value: unknown): C2paValidationItem[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((item) => {
    const record = asRecord(item);
    if (!record) return [];
    const code = typeof record.code === "string" ? record.code : "unknown";
    return [{
      code,
      ...(typeof record.explanation === "string" ? { explanation: record.explanation } : {}),
      ...(typeof record.url === "string" ? { url: record.url } : {}),
    }];
  });
}

function uniqueValidation(items: C2paValidationItem[]) {
  const seen = new Set<string>();
  return items.filter((item) => {
    const key = `${item.code}|${item.explanation ?? ""}|${item.url ?? ""}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function statusFromValidation(hasManifest: boolean, validation: C2paValidationItem[]): C2paVerificationStatus {
  if (!hasManifest) return "not_present";
  if (validation.length === 0) return "valid";

  const codes = validation.map((item) => item.code.toLowerCase());
  if (codes.some((code) => ["invalid", "mismatch", "revoked", "expired", "malformed", "tampered"].some((token) => code.includes(token)))) {
    return "invalid";
  }
  if (codes.some((code) => code.includes("untrusted"))) return "untrusted";
  return "unverifiable";
}

export function normalizeManifestStore(
  storeValue: unknown,
  checkedAt = new Date().toISOString(),
): C2paVerificationReceipt {
  const store = asRecord(storeValue) ?? {};
  const manifests = asRecord(store.manifests) ?? {};
  const manifestLabels = Object.keys(manifests);
  const activeManifest = typeof store.active_manifest === "string"
    ? store.active_manifest
    : typeof store.activeManifest === "string"
      ? store.activeManifest
      : undefined;

  const topLevelValidation = normalizeValidationItems(store.validation_status ?? store.validationStatus);
  const active = activeManifest ? asRecord(manifests[activeManifest]) : null;
  const activeValidation = normalizeValidationItems(active?.validation_status ?? active?.validationStatus);
  const validation = uniqueValidation([...topLevelValidation, ...activeValidation]);
  const hasManifest = manifestLabels.length > 0 || Boolean(activeManifest);
  const status = statusFromValidation(hasManifest, validation);

  const note = status === "valid"
    ? "A C2PA manifest was found and the SDK returned no validation failures in the normalized manifest store."
    : status === "not_present"
      ? "No C2PA manifest was found in the returned manifest store."
      : status === "untrusted"
        ? "A manifest is present, but its signing credential is not trusted under the verifier's current trust configuration."
        : status === "invalid"
          ? "A manifest is present and the verifier reported a validation failure that indicates the asset or manifest should not be treated as valid."
          : "A manifest is present, but the available validation statuses do not support a clean valid/invalid conclusion.";

  return {
    version: "c2pa-verification-v1",
    checkedAt,
    status,
    ...(activeManifest ? { activeManifest } : {}),
    manifestCount: manifestLabels.length,
    manifestLabels,
    validation,
    verifier: "@contentauth/c2pa-web",
    note,
  };
}

