-- Phase 9 developer API hardening: serialize key creation per user so
-- concurrent create requests cannot exceed the 10-active-key contract.

create or replace function public.developer_api_key_create(
  p_user_id uuid,
  p_name text,
  p_prefix text,
  p_hash text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key ops.developer_api_keys%rowtype;
  v_name text := btrim(coalesce(p_name, ''));
begin
  -- Lock the verified Auth identity for the transaction. Every create for the
  -- same user must acquire this row lock before checking the active-key count.
  perform 1
  from auth.users u
  where u.id = p_user_id
    and coalesce(u.is_anonymous, false) = false
    and u.email_confirmed_at is not null
  for update;

  if not found then
    raise exception 'developer_api_requires_verified_account';
  end if;

  if char_length(v_name) < 1 or char_length(v_name) > 80 then
    raise exception 'developer_api_key_name_invalid';
  end if;
  if p_prefix !~ '^pc_sk_[A-Za-z0-9_-]{4,24}$' or p_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'developer_api_key_material_invalid';
  end if;
  if (select count(*) from ops.developer_api_keys k where k.user_id = p_user_id and k.revoked_at is null) >= 10 then
    raise exception 'developer_api_key_limit';
  end if;

  insert into ops.developer_api_keys(user_id, name, key_prefix, key_hash)
  values (p_user_id, v_name, p_prefix, p_hash)
  returning * into v_key;

  return jsonb_build_object(
    'id', v_key.id,
    'name', v_key.name,
    'prefix', v_key.key_prefix,
    'createdAt', v_key.created_at
  );
end;
$$;

revoke all on function public.developer_api_key_create(uuid,text,text,text) from public, anon, authenticated;
grant execute on function public.developer_api_key_create(uuid,text,text,text) to service_role;

import type { C2paVerificationReceipt } from "@/lib/c2pa/types";
import type { FileInspectionReceipt, FileSanitizeResult } from "./types";

export interface ExportableFileVerificationReceipt {
  version: "file-verification-v2";
  generatedAt: string;
  original: {
    sha256: string;
    inspection: FileInspectionReceipt;
    c2pa?: C2paVerificationReceipt;
  };
  sanitized?: {
    sha256: string;
    inspection: FileInspectionReceipt;
    removedFindingIds: string[];
  };
  policy: {
    rawContentStored: false;
    provenanceRemoval: false;
    provenanceBearingAssetsModifiedByDefault: false;
  };
}

export function buildVerificationReceipt(input: {
  originalHash: string;
  inspection: FileInspectionReceipt;
  c2pa?: C2paVerificationReceipt | null;
  cleaned?: FileSanitizeResult | null;
  cleanedHash?: string | null;
}): ExportableFileVerificationReceipt {
  const receipt: ExportableFileVerificationReceipt = {
    version: "file-verification-v2",
    generatedAt: new Date().toISOString(),
    original: {
      sha256: input.originalHash,
      inspection: input.inspection,
      ...(input.c2pa ? { c2pa: input.c2pa } : {}),
    },
    policy: {
      rawContentStored: false,
      provenanceRemoval: false,
      provenanceBearingAssetsModifiedByDefault: false,
    },
  };

  if (input.cleaned && input.cleanedHash) {
    receipt.sanitized = {
      sha256: input.cleanedHash,
      inspection: input.cleaned.after,
      removedFindingIds: input.cleaned.removed.map((item) => item.id),
    };
  }

  return receipt;
}

import { getRequestIdentity } from "@/lib/auth/identity";
import { createAdminClient } from "@/lib/supabase/admin";
import { shouldBootstrapOwner } from "./bootstrap";
import { isAdminRole, type AdminRole } from "./permissions";

export type AdminSession = { userId: string; role: AdminRole };

type AdminRow = { authorized?: boolean; role?: string };

export async function getAdminSession(): Promise<AdminSession | null> {
  const identity = await getRequestIdentity();
  if (!identity || identity.isAnonymous) return null;
  const ownerUserId = process.env.ADMIN_OWNER_USER_ID;
  const ownerEmail = process.env.ADMIN_OWNER_EMAIL;
  const client = createAdminClient();
  if (shouldBootstrapOwner(identity, ownerUserId, ownerEmail)) {
    await client.rpc("ops_bootstrap_owner", { p_owner_id: identity.userId });
  }
  const { data } = await client.rpc("ops_get_admin_role", { p_user_id: identity.userId });
  const row = data as AdminRow | null;
  if (!row?.authorized || !isAdminRole(row.role)) return null;
  return { userId: identity.userId, role: row.role };
}

